/**
 * Branch Management Module — Database Migration Script (Production-Ready)
 *
 * Purpose:
 * Safely alters and extends the database schema for the Branch Management
 * module (Branches, Users/Staff, Roles, Branch Assignments, Number Sequences,
 * Branch GST Settings, Taxes, and Branch Tax Assignments).
 *
 * Confirmed Business Decisions & Safety Rules:
 * - Transactional (BEGIN ... COMMIT / ROLLBACK).
 * - Idempotent (can be executed multiple times without failure or duplicated state).
 * - Branch codes are generated by the backend using number_sequences (BRANCH);
 *   no random UUID database defaults are used.
 * - Facility type is a fixed list (HOSPITAL_PHARMACY, RETAIL_DISPENSARY, CENTRAL_WAREHOUSE).
 * - Branch contact details are plain text fields, NOT user foreign keys.
 * - Invoice prefix is backend-generated.
 * - Every branch has its own GSTIN (1:1 branch_gst_settings table).
 * - No fabricated GST data is inserted during migration; GST settings are configured later.
 * - No default tax seeding; existing taxes preserved, taxes table may exist empty.
 * - No automatic tax assignments to branches; existing branch_tax_assignments preserved.
 * - Missing authoritative system roles seeded without overwriting custom roles.
 * - No data copying from branches.phone to branches.contact_phone.
 * - Staff ID is backend-generated using number_sequences (STAFF); users table remains global identity.
 * - No speculative fields (auto_saas_tax removed).
 * - No plaintext password data or invitation workflows.
 */

const { pool } = require("./connection");

const migrateBranchManagement = async () => {
  const client = await pool.connect();

  try {
    console.log(
      "Beginning Branch Management database migration (production correction pass)...",
    );
    await client.query("BEGIN");

    // ============================================================
    // 1. USERS TABLE EXTENSIONS (Staff fields)
    // ============================================================
    console.log(
      "1. Updating users table with staff columns and non-unique index...",
    );

    await client.query(`
      ALTER TABLE users ADD COLUMN IF NOT EXISTS staff_id VARCHAR(50);
      ALTER TABLE users ADD COLUMN IF NOT EXISTS phone VARCHAR(50);
      ALTER TABLE users ADD COLUMN IF NOT EXISTS professional_registration_number VARCHAR(100);
      ALTER TABLE users ADD COLUMN IF NOT EXISTS working_shift VARCHAR(100);
    `);

    // Non-unique index on staff_id (preserves organisation-scoped sequence flexibility)
    await client.query(`
      CREATE INDEX IF NOT EXISTS idx_users_staff_id ON users (staff_id) WHERE staff_id IS NOT NULL;
    `);

    // ============================================================
    // 2. BRANCHES TABLE EXTENSIONS
    // ============================================================
    console.log("2. Updating branches table columns and constraints...");

    await client.query(`
      ALTER TABLE branches ADD COLUMN IF NOT EXISTS branch_code VARCHAR(50);
      ALTER TABLE branches ADD COLUMN IF NOT EXISTS facility_type VARCHAR(50) DEFAULT 'RETAIL_DISPENSARY';
      ALTER TABLE branches ADD COLUMN IF NOT EXISTS contact_person VARCHAR(150);
      ALTER TABLE branches ADD COLUMN IF NOT EXISTS contact_phone VARCHAR(50);
      ALTER TABLE branches ADD COLUMN IF NOT EXISTS contact_email VARCHAR(255);
      ALTER TABLE branches ADD COLUMN IF NOT EXISTS operating_hours VARCHAR(150);
      ALTER TABLE branches ADD COLUMN IF NOT EXISTS drug_license_number VARCHAR(150);
      ALTER TABLE branches ADD COLUMN IF NOT EXISTS invoice_prefix VARCHAR(50);
      ALTER TABLE branches ADD COLUMN IF NOT EXISTS status VARCHAR(30) DEFAULT 'ACTIVE';
    `);

    // Ensure random UUID default is removed — branch_code is generated via number_sequences
    await client.query(`
      ALTER TABLE branches ALTER COLUMN branch_code DROP DEFAULT;
      ALTER TABLE branches ALTER COLUMN branch_code DROP NOT NULL;
    `);

    // Safely backfill any existing branches that lack a branch_code using deterministic numbering
    await client.query(`
      WITH numbered_branches AS (
        SELECT id, 'BR-' || LPAD((ROW_NUMBER() OVER (PARTITION BY organisation_id ORDER BY created_at))::text, 3, '0') AS gen_code
        FROM branches
        WHERE branch_code IS NULL
      )
      UPDATE branches b
      SET branch_code = nb.gen_code
      FROM numbered_branches nb
      WHERE b.id = nb.id;
    `);

    // Ensure status and facility_type defaults are set on any null rows
    await client.query(`
      UPDATE branches SET status = 'ACTIVE' WHERE status IS NULL;
      UPDATE branches SET facility_type = 'RETAIL_DISPENSARY' WHERE facility_type IS NULL;
    `);

    // Apply constraints on branches
    await client.query(`
      ALTER TABLE branches DROP CONSTRAINT IF EXISTS branches_organisation_code_unique;
      ALTER TABLE branches ADD CONSTRAINT branches_organisation_code_unique UNIQUE (organisation_id, branch_code);

      ALTER TABLE branches DROP CONSTRAINT IF EXISTS branches_facility_type_check;
      ALTER TABLE branches ADD CONSTRAINT branches_facility_type_check
        CHECK (facility_type IN ('HOSPITAL_PHARMACY', 'RETAIL_DISPENSARY', 'CENTRAL_WAREHOUSE'));

      ALTER TABLE branches DROP CONSTRAINT IF EXISTS branches_status_check;
      ALTER TABLE branches ADD CONSTRAINT branches_status_check
        CHECK (status IN ('ACTIVE', 'INACTIVE'));
    `);

    // ============================================================
    // 3. ROLES TABLE EXTENSIONS & CLEANUP
    // ============================================================
    console.log(
      "3. Updating roles table with role_identifier and clearance_level...",
    );

    await client.query(`
      ALTER TABLE roles ADD COLUMN IF NOT EXISTS role_identifier VARCHAR(50);
      ALTER TABLE roles ADD COLUMN IF NOT EXISTS clearance_level VARCHAR(50) DEFAULT 'STANDARD_POS';
      ALTER TABLE roles ADD COLUMN IF NOT EXISTS is_system_role BOOLEAN NOT NULL DEFAULT FALSE;
    `);

    // Backfill any existing roles where role_identifier or clearance_level is null
    await client.query(`
      UPDATE roles
      SET role_identifier = UPPER(REPLACE(name, ' ', '_'))
      WHERE role_identifier IS NULL;

      UPDATE roles
      SET clearance_level = 'STANDARD_POS'
      WHERE clearance_level IS NULL;
    `);

    await client.query(`
      ALTER TABLE roles DROP CONSTRAINT IF EXISTS roles_organisation_identifier_unique;
      ALTER TABLE roles ADD CONSTRAINT roles_organisation_identifier_unique
        UNIQUE (organisation_id, role_identifier);

      ALTER TABLE roles DROP CONSTRAINT IF EXISTS roles_clearance_level_check;
      ALTER TABLE roles ADD CONSTRAINT roles_clearance_level_check
        CHECK (clearance_level IN ('ADMIN', 'CLINICAL_DISPENSING', 'MANAGEMENT', 'STANDARD_POS', 'AUDIT'));
    `);

    // Seed ONLY missing authoritative system roles without overwriting custom roles
    console.log(
      "3b. Seeding missing authoritative system roles for organisations...",
    );
    const orgsResult = await client.query("SELECT id FROM organisations");
    const systemRoles = [
      {
        name: "Administrator",
        identifier: "ADMIN",
        clearance: "ADMIN",
        desc: "Full administrative access to all branch operations, staff management, and system configuration.",
      },
      {
        name: "Pharmacist",
        identifier: "PHARMACIST",
        clearance: "CLINICAL_DISPENSING",
        desc: "Dispensing, prescription validation, stock movements and patient counseling support.",
      },
      {
        name: "Billing / Cashier",
        identifier: "CASHIER",
        clearance: "STANDARD_POS",
        desc: "Fast Point-of-Sale billing, payment collection, standard cash counter operations.",
      },
    ];

    for (const org of orgsResult.rows) {
      for (const role of systemRoles) {
        // 1. Check if role already exists by identifier in this organisation
        const existingById = await client.query(
          "SELECT id, is_system_role, name FROM roles WHERE organisation_id = $1 AND role_identifier = $2",
          [org.id, role.identifier],
        );

        if (existingById.rows.length > 0) {
          // Already exists by identifier - ensure flagged as system role
          await client.query(
            "UPDATE roles SET is_system_role = TRUE WHERE id = $1 AND is_system_role = FALSE",
            [existingById.rows[0].id],
          );
          continue;
        }

        // 2. Check if a role exists with matching name
        const existingByName = await client.query(
          "SELECT id, is_system_role, role_identifier FROM roles WHERE organisation_id = $1 AND name = $2",
          [org.id, role.name],
        );

        if (existingByName.rows.length > 0) {
          const matched = existingByName.rows[0];
          // Do NOT overwrite existing custom roles! Only link if it's already an un-identified system role
          if (matched.is_system_role || matched.role_identifier === null) {
            await client.query(
              `UPDATE roles
               SET role_identifier = $1, clearance_level = $2, is_system_role = TRUE
               WHERE id = $3`,
              [role.identifier, role.clearance, matched.id],
            );
          }
        } else {
          // 3. Neither identifier nor name exists: insert missing authoritative system role
          await client.query(
            `INSERT INTO roles (organisation_id, name, role_identifier, clearance_level, is_system_role, description)
             VALUES ($1, $2, $3, $4, TRUE, $5)`,
            [org.id, role.name, role.identifier, role.clearance, role.desc],
          );
        }
      }
    }

    // ============================================================
    // 4. BRANCH ASSIGNMENTS EXTENSIONS (Primary Branch distinction)
    // ============================================================
    console.log(
      "4. Updating branch_assignments with is_primary metadata and partial unique index...",
    );

    await client.query(`
      ALTER TABLE branch_assignments ADD COLUMN IF NOT EXISTS is_primary BOOLEAN NOT NULL DEFAULT FALSE;
    `);

    await client.query(`
      CREATE UNIQUE INDEX IF NOT EXISTS branch_assignments_one_primary_per_membership
      ON branch_assignments (membership_id)
      WHERE is_primary = TRUE;
    `);

    // ============================================================
    // 5. NUMBER SEQUENCES EXTENSIONS (BRANCH & STAFF sequence types)
    // ============================================================
    console.log(
      "5. Updating number_sequences constraint to include BRANCH and STAFF sequence types...",
    );

    await client.query(`
      ALTER TABLE number_sequences DROP CONSTRAINT IF EXISTS number_sequences_type_check;
      ALTER TABLE number_sequences ADD CONSTRAINT number_sequences_type_check
        CHECK (sequence_type IN ('CUSTOMER', 'PRESCRIPTION', 'INVOICE', 'RECEIPT', 'RETURN', 'BRANCH', 'STAFF', 'PURCHASE', 'STOCK_TRANSFER', 'GOODS_RECEIPT'));
    `);

    // ============================================================
    // 6. BRANCH GST SETTINGS (1:1 with branches)
    // ============================================================
    console.log(
      "6. Creating branch_gst_settings table without speculative fields...",
    );

    await client.query(`
      CREATE TABLE IF NOT EXISTS branch_gst_settings (
          id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
          organisation_id UUID NOT NULL REFERENCES organisations (id) ON DELETE CASCADE,
          branch_id UUID NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
          gstin VARCHAR(20) NOT NULL,
          legal_name VARCHAR(200),
          trade_name VARCHAR(200),
          state VARCHAR(100),
          state_code VARCHAR(10),
          gst_scheme VARCHAR(30) NOT NULL DEFAULT 'REGULAR',
          tax_inclusive_pricing BOOLEAN NOT NULL DEFAULT TRUE,
          auto_interstate_split BOOLEAN NOT NULL DEFAULT TRUE,
          e_invoicing_enabled BOOLEAN NOT NULL DEFAULT FALSE,
          status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',
          created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
          updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
          CONSTRAINT branch_gst_settings_branch_unique UNIQUE (branch_id),
          CONSTRAINT branch_gst_settings_scheme_check CHECK (gst_scheme IN ('REGULAR', 'COMPOSITION')),
          CONSTRAINT branch_gst_settings_status_check CHECK (status IN ('ACTIVE', 'INACTIVE'))
      );

      CREATE INDEX IF NOT EXISTS idx_branch_gst_settings_org_branch
      ON branch_gst_settings (organisation_id, branch_id);

      -- Drop speculative column if it exists from previous runs
      ALTER TABLE branch_gst_settings DROP COLUMN IF EXISTS auto_saas_tax;
    `);

    // Remove any fabricated GST settings from previous migration runs
    await client.query(`
      DELETE FROM branch_gst_settings
      WHERE gstin = '27AABCF1234F1Z5'
         OR legal_name = 'Flora Institute Healthcare & Pharmacy Pvt Ltd';
    `);

    // ============================================================
    // 7. TAX DEFINITIONS (Organisation-scoped)
    // ============================================================
    console.log("7. Ensuring taxes table exists (no default tax seeding)...");

    await client.query(`
      CREATE TABLE IF NOT EXISTS taxes (
          id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
          organisation_id UUID NOT NULL REFERENCES organisations (id) ON DELETE CASCADE,
          name VARCHAR(100) NOT NULL,
          tax_type VARCHAR(50) NOT NULL,
          rate NUMERIC(5, 2) NOT NULL DEFAULT 0.00,
          is_default BOOLEAN NOT NULL DEFAULT FALSE,
          is_active BOOLEAN NOT NULL DEFAULT TRUE,
          description TEXT,
          created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
          updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
          CONSTRAINT taxes_rate_check CHECK (rate >= 0 AND rate <= 100),
          CONSTRAINT taxes_tax_type_check CHECK (tax_type IN ('CENTRAL_TAX', 'STATE_TAX', 'VAT_TAX', 'CESS', 'OTHER')),
          CONSTRAINT taxes_organisation_name_unique UNIQUE (organisation_id, name)
      );

      CREATE INDEX IF NOT EXISTS idx_taxes_organisation_id ON taxes (organisation_id);
    `);

    // No default tax seeding — the taxes table may exist empty until the application explicitly creates tax definitions.
    // Existing tax definitions are preserved intact.

    // ============================================================
    // 8. BRANCH TAX ASSIGNMENTS (N:M Junction table)
    // ============================================================
    console.log("8. Ensuring branch_tax_assignments junction table exists...");

    await client.query(`
      CREATE TABLE IF NOT EXISTS branch_tax_assignments (
          branch_id UUID NOT NULL REFERENCES branches (id) ON DELETE CASCADE,
          tax_id UUID NOT NULL REFERENCES taxes (id) ON DELETE CASCADE,
          is_applied BOOLEAN NOT NULL DEFAULT TRUE,
          created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
          PRIMARY KEY (branch_id, tax_id)
      );

      CREATE INDEX IF NOT EXISTS idx_branch_tax_assignments_tax_id ON branch_tax_assignments (tax_id);
    `);

    // Preserving all existing branch_tax_assignments — zero automatic assignments are created.

    await client.query("COMMIT");
    console.log(
      "✓ Branch Management database migration (production-ready) completed successfully!",
    );
  } catch (error) {
    await client.query("ROLLBACK");
    console.error("Migration failed. Rolled back all changes.");
    console.error(error);
    throw error;
  } finally {
    client.release();
  }
};

if (require.main === module) {
  migrateBranchManagement()
    .then(() => {
      console.log("Migration runner finished.");
      process.exit(0);
    })
    .catch((err) => {
      console.error("Migration runner terminated with error:", err.message);
      process.exit(1);
    });
}

module.exports = { migrateBranchManagement };
